do $$declare s text;begin select pg_get_functiondef('public.pqr_complete_edit(uuid,boolean,text)'::regprocedure) into s;s:=replace(s,$n$v_row.code not like 'EDC-%'$n$,$r$coalesce(v_row.data->>'requestType',case when v_row.code like 'EDC-%' then 'EDC' else 'PQR' end)<>'EDC'$r$);execute s;end;$$;
alter table public.pqr_tickets drop constraint pqr_edc_solo_validacion;
alter table public.pqr_tickets add constraint pqr_edc_solo_validacion check(coalesce(data->>'requestType',case when code like 'EDC-%' then 'EDC' else 'PQR' end)<>'EDC' or data->>'redigitType' is null or data->>'redigitType'='Validación');
do $$declare s text;begin select pg_get_constraintdef(oid) into s from pg_constraint where conrelid='public.pqr_tickets'::regclass and conname='pqr_manual_sin_cuenta_comercial';s:=replace(s,$n$((data ->> 'requestType'::text) = 'PQR'::text)$n$,$r$((data ->> 'requestType'::text) = ANY (ARRAY['PQR'::text,'RDG'::text,'EDC'::text]))$r$);alter table public.pqr_tickets drop constraint pqr_manual_sin_cuenta_comercial;execute 'alter table public.pqr_tickets add constraint pqr_manual_sin_cuenta_comercial '||s;end;$$;
